sp_SalvarConfigFiscal	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_SalvarConfigFiscal`(\n\n    IN p_idEmpresa INT, IN p_cnpjFiscal VARCHAR(18), IN p_inscricaoEstadual VARCHAR(20),\n\n    IN p_inscricaoMunicipal VARCHAR(20), IN p_regimeTributario TINYINT, IN p_ambiente TINYINT,\n\n    IN p_serieNFe VARCHAR(3), IN p_serieNFCe VARCHAR(3), IN p_proximoNumNFe INT,\n\n    IN p_proximoNumNFCe INT, IN p_aliqPadraoICMS DECIMAL(5,2),\n\n    IN p_aliqPadraoPIS DECIMAL(5,2), IN p_aliqPadraoCOFINS DECIMAL(5,2)\n\n)\nBEGIN\n\n    INSERT INTO EmpresaConfigFiscal (\n\n        idEmpresa, cnpjFiscal, inscricaoEstadual, inscricaoMunicipal,\n\n        regimeTributario, ambiente, serieNFe, serieNFCe, proximoNumNFe, proximoNumNFCe,\n\n        aliqPadraoICMS, aliqPadraoPIS, aliqPadraoCOFINS, fAtivo\n\n    ) VALUES (\n\n        p_idEmpresa, p_cnpjFiscal, p_inscricaoEstadual, p_inscricaoMunicipal,\n\n        p_regimeTributario, p_ambiente, p_serieNFe, p_serieNFCe, p_proximoNumNFe, p_proximoNumNFCe,\n\n        p_aliqPadraoICMS, p_aliqPadraoPIS, p_aliqPadraoCOFINS, 1\n\n    )\n\n    ON DUPLICATE KEY UPDATE\n\n        cnpjFiscal=p_cnpjFiscal, inscricaoEstadual=p_inscricaoEstadual,\n\n        inscricaoMunicipal=p_inscricaoMunicipal, regimeTributario=p_regimeTributario,\n\n        ambiente=p_ambiente, serieNFe=p_serieNFe, serieNFCe=p_serieNFCe,\n\n        proximoNumNFe=p_proximoNumNFe, proximoNumNFCe=p_proximoNumNFCe,\n\n        aliqPadraoICMS=p_aliqPadraoICMS, aliqPadraoPIS=p_aliqPadraoPIS,\n\n        aliqPadraoCOFINS=p_aliqPadraoCOFINS;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
